function familyAddReflection(anchor){if(!familyInlineCanStart())return;const data=familyInlineData(anchor),keys=['mine','bora'].filter(k=>!data[k]);if(!keys.length)return;if(keys.length===1){familyStartInline(anchor,keys[0]);return}const d=familyDialog('배운 점',`<div class="family-reflection-options">${keys.map(k=>`<button type="button" data-reflection="${k}" aria-label="${k==='mine'?'민수':'보라'}의 생각">${personIdentity(k)}</button>`).join('')}</div>`);d.querySelectorAll('[data-reflection]').forEach(b=>b.onclick=()=>{const key=b.dataset.reflection;d.close();familyStartInline(anchor,key)})}
function familyEditResource(anchor,index){if(!familyInlineCanStart()||familyInlineLocks.has('resources'))return;const data=familyInlineData(anchor),baseline=data.resources.map(x=>({...x})),old=index>=0?baseline[index]:{title:'',url:''};if(!old)return;const d=familyDialog(index<0?'자료 추가':'자료 수정',`<form class="family-form"><label class="family-field">자료 이름<input name="title" maxlength="100" value="${esc(old.title)}"></label><label class="family-field">링크<input name="url" type="url" maxlength="2000" value="${esc(old.url)}" placeholder="https://" required></label><p class="family-form-error" role="alert"></p><button class="primary family-save" type="submit">저장</button></form>`),form=d.querySelector('form');d.isDirty=()=>form.elements.title.value!==old.title||form.elements.url.value!==old.url;form.onsubmit=async e=>{e.preventDefault();const entry={title:form.elements.title.value.trim(),url:form.elements.url.value.trim()};if(!safeUrl(entry.url)){d.querySelector('.family-form-error').textContent='자료 링크를 확인해 주세요.';return}const updated=baseline.map(x=>({...x}));if(index<0)updated.push(entry);else updated[index]=entry;if(familyInlineEqual(updated,baseline)){d.close();return}d.setBusy(true);try{const result=await familyInlineSubmitPatch(anchor,'resources',{resources:updated},{resources:baseline});if(!result)return;d.isDirty=()=>false;d.close();if(location.hash===familySessionLink(anchor))familyRenderInlineFields(anchor,result)}catch(err){d.querySelector('.family-form-error').textContent=err.message||'저장하지 못했어요.'}finally{if(d.isConnected)d.setBusy(false)}};form.elements.title.focus()}
function familyResourceMenu(anchor,index){if(!familyInlineCanStart()||familyInlineLocks.has('resources'))return;const baseline=familyInlineData(anchor).resources.map(x=>({...x})),item=baseline[index];if(!item)return;const d=familyDialog(item.title||'자료',`<div class="family-photo-actions"><button type="button" data-link-action="edit">수정</button><button type="button" data-link-action="up" ${index===0?'disabled':''}>앞으로</button><button type="button" data-link-action="down" ${index===baseline.length-1?'disabled':''}>뒤로</button><button type="button" data-link-action="delete">삭제</button></div><p class="family-form-error" role="alert"></p>`);d.querySelectorAll('[data-link-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.linkAction;if(action==='edit'){d.close();familyEditResource(anchor,index);return}if(action==='delete'&&!confirm('이 자료를 삭제할까요?'))return;const list=baseline.map(x=>({...x}));if(action==='delete')list.splice(index,1);else{const j=index+(action==='up'?-1:1);if(j<0||j>=list.length)return;[list[index],list[j]]=[list[j],list[index]]}d.setBusy(true);try{const result=await familyInlineSubmitPatch(anchor,'resources',{resources:list},{resources:baseline});if(!result)return;d.close();if(location.hash===familySessionLink(anchor))familyRenderInlineFields(anchor,result)}catch(err){d.querySelector('.family-form-error').textContent=err.message||'저장하지 못했어요.'}finally{if(d.isConnected)d.setBusy(false)}})}

function familyOpenSessionMenu(anchor){const d=familyDialog('가족 숭배',`<div class="family-photo-actions"><button type="button" id="family-remove">회차 삭제</button></div>`);d.querySelector('#family-remove').onclick=()=>{d.close();familyRemoveSession(anchor)}}

// Clicking an empty row has the same result as its accessible + button.
function familyBindEmptyRows(anchor){
 const bind=(selector,empty,act)=>{const row=document.querySelector(selector);if(!row)return;row.addEventListener('click',e=>{if(e.target.closest('button,a,input,textarea,select,form'))return;if(empty())act()})};
 bind('.family-preparation',()=>!!document.querySelector('#family-field-preparation .family-inline-empty'),()=>familyStartInline(anchor,'preparation'));
 bind('.family-resources',()=>!document.getElementById('family-field-resources')?.children.length,()=>familyEditResource(anchor,-1));
 bind('.family-content-photos',()=>!document.querySelector('.family-photo-grid'),()=>document.getElementById('family-photo-add')?.click());
 bind('.family-reflections',()=>['common','mine','bora'].every(k=>!document.getElementById('family-field-'+k)?.children.length),()=>familyAddReflection(anchor));
}
